package com.myblog.user.service;
import com.myblog.user.exception.BusinessException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class SocialService{
 private final JdbcTemplate jdbc;private final SocialHubService hub;public SocialService(JdbcTemplate jdbc,SocialHubService hub){this.jdbc=jdbc;this.hub=hub;} /* TRAVEL_SOCIAL_V12 TRAVEL_SOCIAL_V121 */
 private Map<String,Object> travel(long id,long user,boolean lock){var rows=jdbc.queryForList("SELECT user_id,visibility,is_published FROM travel_project WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty())throw new BusinessException(404,"旅行不存在");var p=rows.get(0);boolean owner=((Number)p.get("user_id")).longValue()==user;boolean readable=owner||("PUBLIC".equals(p.get("visibility"))&&((Number)p.get("is_published")).intValue()==1);if(!readable)throw new BusinessException(403,"旅行未公开");return p;}
 public Map<String,Object> state(long id,long user){var p=travel(id,user,false);long author=((Number)p.get("user_id")).longValue();return Map.of("authorId",author,"liked",count("SELECT COUNT(*) FROM travel_like WHERE travel_id=? AND user_id=?",id,user)>0,"following",count("SELECT COUNT(*) FROM user_follow WHERE follower_id=? AND followed_id=?",user,author)>0,"likeCount",count("SELECT COUNT(*) FROM travel_like WHERE travel_id=?",id));}
 private long count(String sql,Object...args){Long v=jdbc.queryForObject(sql,Long.class,args);return v==null?0:v;}
 @Transactional public Map<String,Object> like(long id,long user,boolean add){var trip=travel(id,user,true);boolean fresh=add&&count("SELECT COUNT(*) FROM travel_like WHERE travel_id=? AND user_id=?",id,user)==0;if(add)jdbc.update("INSERT INTO travel_like(travel_id,user_id) VALUES(?,?) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id)",id,user);else jdbc.update("DELETE FROM travel_like WHERE travel_id=? AND user_id=?",id,user);jdbc.update("UPDATE travel_project SET like_count=(SELECT COUNT(*) FROM travel_like WHERE travel_id=?) WHERE id=?",id,id);if(fresh)hub.notifyEvent(((Number)trip.get("user_id")).longValue(),user,"TRAVEL_LIKE",null,id,"喜欢了你的旅行");return state(id,user);}
 @Transactional public boolean follow(long target,long user,boolean add){if(target==user)throw new BusinessException("不能关注自己");if(jdbc.queryForList("SELECT id FROM user WHERE id=? AND status=1 FOR UPDATE",user).isEmpty())throw new BusinessException(401,"当前用户不存在或已禁用");if(count("SELECT COUNT(*) FROM user WHERE id=? AND status=1",target)==0)throw new BusinessException(404,"作者不存在");boolean fresh=add&&count("SELECT COUNT(*) FROM user_follow WHERE follower_id=? AND followed_id=?",user,target)==0;if(add)jdbc.update("INSERT INTO user_follow(follower_id,followed_id) VALUES(?,?) ON DUPLICATE KEY UPDATE followed_id=VALUES(followed_id)",user,target);else jdbc.update("DELETE FROM user_follow WHERE follower_id=? AND followed_id=?",user,target);if(fresh)hub.notifyEvent(target,user,"USER_FOLLOW",null,null,"关注了你");hub.syncFollow(user,target,add);return count("SELECT COUNT(*) FROM user_follow WHERE follower_id=? AND followed_id=?",user,target)>0;}
 public List<Map<String,Object>> comments(long id,long user,int page){travel(id,user,false);int safe=Math.min(500,Math.max(1,page));return jdbc.queryForList("SELECT c.id,c.user_id AS userId,c.content,c.created_at AS createdAt,COALESCE(NULLIF(u.nickname,''),u.username) AS author FROM travel_comment c JOIN user u ON u.id=c.user_id WHERE c.travel_id=? ORDER BY c.id DESC LIMIT 20 OFFSET ?",id,(safe-1)*20);}
 @Transactional public boolean comment(long id,long user,String content){travel(id,user,true);String c=content==null?"":content.trim();if(c.isEmpty()||c.length()>1000)throw new BusinessException("评论须为1至1000字");if(count("SELECT COUNT(*) FROM travel_comment WHERE user_id=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 MINUTE)",user)>=10)throw new BusinessException(429,"评论太频繁，请稍后再试");jdbc.update("INSERT INTO travel_comment(travel_id,user_id,content) VALUES(?,?,?)",id,user,c);hub.notifyEvent(((Number)jdbc.queryForMap("SELECT user_id FROM travel_project WHERE id=?",id).get("user_id")).longValue(),user,"TRAVEL_COMMENT",null,id,"评论了你的旅行");return true;}
 @Transactional public boolean deleteComment(long id,long comment,long user){var p=travel(id,user,true);long owner=((Number)p.get("user_id")).longValue();int n=jdbc.update("DELETE FROM travel_comment WHERE id=? AND travel_id=? AND (user_id=? OR ?=?)",comment,id,user,user,owner);if(n==0)throw new BusinessException(404,"评论不存在或无权删除");return true;}
}
